Rule.Source:
import sailpoint.api.Aggregator;
import sailpoint.connector.Connector;
import sailpoint.connector.ConnectorFactory;
import sailpoint.object.Application;
import sailpoint.object.Attributes;
import sailpoint.object.ResourceObject;
import sailpoint.object.TaskResult;
import sailpoint.tools.CloseableIterator;

// Defaults used when run from the console without arguments
String APP_NAME   = "HR Authoritative CSV";
String ACCOUNT_ID = "1000";

String app_name = (void == appName || appName == null) ? APP_NAME : appName;
String acct_id  = (void == accountId || accountId == null) ? ACCOUNT_ID : accountId;

Application app = context.getObjectByName(Application.class, app_name);
if (app == null) {
    return "ERROR: application '" + app_name + "' not found";
}

Connector connector = ConnectorFactory.getConnector(app, null);
ResourceObject account = null;

// 1. Fetch just this account if the connector supports it
try {
    account = connector.getObject("account", acct_id, null);
} catch (Exception e) {
    log.debug("getObject not supported for " + app_name + ", scanning instead: " + e);
}

// 2. Otherwise read all accounts and keep the matching one (delimited files)
if (account == null) {
    CloseableIterator it = connector.iterateObjects("account", null, null);
    try {
        while (it.hasNext()) {
            ResourceObject ro = (ResourceObject) it.next();
            if (acct_id.equalsIgnoreCase(ro.getIdentity())) {
                account = ro;
                break;
            }
        }
    } finally {
        it.close();
    }
}

if (account == null) {
    return "ERROR: account '" + acct_id + "' not found in " + app_name;
}

// 3. Aggregate it. noOptimizeReaggregation makes IIQ apply it even if it
//    thinks nothing changed.
Attributes args = new Attributes();
args.put("noOptimizeReaggregation", "true");
args.put("promoteAttributes", "true");
Aggregator aggregator = new Aggregator(context, args);
TaskResult result = aggregator.aggregate(app, account);

String summary = "Aggregated " + app_name + " account " + acct_id;
if (result != null) {
    summary += " | created=" + result.getAttribute("created")
             + " updated=" + result.getAttribute("updated")
             + " total=" + result.getAttribute("total");
    if (result.getErrors() != null && !result.getErrors().isEmpty()) {
        summary += " | ERRORS: " + result.getErrors();
    }
}
return summary + "\nAccount attributes read: " + account.getAttributes();
